<?php declare(strict_types=1); ?>
<form method="get" class="dwf-folder-search">
<?php foreach($workflowBase as$wfKey=>$wfValue)if(!in_array($wfKey,['wf_folder','wf_folder_search'],true))echo $wfHidden((string)$wfKey,$wfValue);echo $wfHidden('wf_folder',$wfFolderId); ?>
<label><?= $wfEsc($wfI('Ordnername oder Kennung')) ?><input class="form-control" type="search" name="wf_folder_search" value="<?= $wfEsc($wfPrepared['folder_search']) ?>"><small><?= $wfEsc($wfF('Bis zu {count} Zeichen.',['count'=>240])) ?></small></label><button class="btn btn-outline theme-secondary dwf-button"><?= $wfEsc($wfI('Ordner suchen')) ?></button>
<?php if($wfPrepared['folder_search']!==''):?><a href="<?= $wfEsc($wfUrl(['wf_folder_search'=>''])) ?>"><?= $wfEsc($wfI('Ordnersuche leeren')) ?></a><?php endif ?>
</form>
<?php if($wfPrepared['folder_search_error']!==''):?><p class="dwf-alert" role="alert"><?= $wfEsc($wfI($wfPrepared['folder_search_error'])) ?></p><?php endif ?>
<?php if($wfFolderTree->detached()):?><p class="dwf-help"><?= $wfEsc($wfI('Einige Ordner haben keinen vollständigen übergeordneten Pfad. Ihre ursprünglichen Zuordnungen bleiben bis zu einer bewussten Korrektur erhalten.')) ?></p><?php endif ?>
<nav aria-label="<?= $wfEsc($wfI('Workflow-Ordner')) ?>"><ol class="dwf-folder-tree">
<?php foreach($wfPrepared['folder_rows']as$wfFolderNode):?><li style="--dwf-folder-depth:<?= min(6,$wfFolderNode['depth']) ?>" data-dwf-folder-id="<?= $wfEsc($wfFolderNode['id']) ?>"><a class="dwf-folder-link" href="<?= $wfEsc($wfUrl(['wf_folder'=>$wfFolderNode['id'],'wf_page'=>1])) ?>" <?= $wfFolderId===$wfFolderNode['id']?'aria-current="page"':'' ?>><?= $wfEsc($wfFolderNode['name']) ?><small><?= $wfEsc($wfFolderNode['detached']?$wfI('Zuordnung prüfen'):$wfF('Ebene {level}',['level'=>$wfFolderNode['depth']+1])) ?></small><?php if($wfFolderTree->ambiguous($wfFolderNode['id'])):?><small class="dwf-folder-reference"><?= $wfEsc($wfFolderNode['id']) ?></small><?php endif ?></a></li><?php endforeach ?>
</ol></nav>
<?php if(!$wfPrepared['folder_rows']&&$wfPrepared['folder_search_error']===''):?><p class="dwf-muted"><?= $wfEsc($wfI('Keine passenden Arbeitsordner.')) ?></p><?php endif ?>
<?php if($wfWrite):
 $wfFolderPost=$wfPosted('document-workflow-folder-save');$wfFolderOpen=$wfFolderPost||($wfMode!=='creations'&&$wfPrepared['receipt_kind']==='folder');
 if(!$wfFolderOpen):?><a class="dwf-folder-create-link" href="<?= $wfEsc($wfUrl(['wf_creation_kind'=>'folder','wf_creation_key'=>$wfPrepared['creation_keys']['folder']])) ?>#dwf-new-folder"><?= $wfEsc($wfI('Ordner anlegen')) ?></a>
 <?php else:?><details id="dwf-new-folder" class="dwf-folder-create" open><summary><?= $wfEsc($wfI('Ordner anlegen')) ?></summary><form method="post" data-dwf-create-form action="<?= $wfEsc($wfUrl(['wf_folder'=>$wfFolderId,'wf_creation_kind'=>'folder','wf_creation_key'=>$wfPrepared['creation_keys']['folder']])) ?>"><?php $wfForm('document-workflow-folder-save'); ?><label><?= $wfEsc($wfI('Name')) ?><textarea class="form-control" name="wf_name" rows="2" required data-dwf-character-limit="240"><?= $wfEsc($wfFolderPost?$wfText($_POST,'wf_name'):'') ?></textarea><small><?= $wfEsc($wfF('Bis zu {count} Zeichen.',['count'=>240])) ?></small></label><label><?= $wfEsc($wfI('Übergeordneter Ordner')) ?><select class="form-control" name="wf_parent"><?php $wfFolderOptions($wfFolderPost?$wfText($_POST,'wf_parent'):$wfFolderId); ?></select></label><button class="btn btn-outline theme-secondary dwf-button"><?= $wfEsc($wfI('Ordner speichern')) ?></button><?php echo $wfHidden('wf_folder_complete','1');$wfCreationRecovery('folder'); ?></form></details><?php endif;endif ?>
